// ============================================================
// NAGIOS ALERT REPORT - n8n
// Source: Analyze Critical Logs
// ============================================================

// IMPORTANT:
// Get data directly from the "Analyze Critical Logs" node.
// Do NOT use $json.stdout here because stdout is not present
// in the Analyze Critical Logs output.

const raw = $('Analyze Critical Logs').first().json;

// Debug: uncomment the next line if you need to see the raw shape again
// console.log('RAW ANALYZE CRITICAL LOGS OUTPUT:', JSON.stringify(raw, null, 2));

// ============================================================
// RESILIENT FIELD LOOKUP
// ============================================================
// Some nodes nest their summary under a sub-object (e.g. nagios_summary),
// and field names sometimes vary (error_count vs error_failed_count).
// This helper checks the flat object first, then a nested "nagios_summary"
// object, then falls back to 0.

const nested = raw.nagios_summary || raw.summary || {};

function getField(...names) {
  for (const name of names) {
    if (raw[name] !== undefined && raw[name] !== null) return raw[name];
    if (nested[name] !== undefined && nested[name] !== null) return nested[name];
  }
  return 0;
}

function getArrayField(...names) {
  for (const name of names) {
    if (Array.isArray(raw[name])) return raw[name];
    if (Array.isArray(nested[name])) return nested[name];
  }
  return [];
}


// ============================================================
// GET COUNTS
// ============================================================

const totalLogLines   = Number(getField('total_log_lines', 'totalLogLines') || 0);

const criticalCount   = Number(getField('critical_count', 'criticalCount') || 0);
const downCount       = Number(getField('down_count', 'downCount') || 0);
const unreachableCount = Number(getField('unreachable_count', 'unreachableCount') || 0);
const errorCount      = Number(getField('error_count', 'error_failed_count', 'errorCount', 'errorFailedCount') || 0);
const warningCount    = Number(getField('warning_count', 'warningCount') || 0);


// ============================================================
// GET LOG DETAILS
// ============================================================

const criticalLogs = getArrayField('critical_logs', 'criticalLogs');


// ============================================================
// DEBUG SUMMARY (visible in Output / console)
// ============================================================

const debugInfo = {
  resolved_from: {
    used_flat_object: Object.keys(raw).some(k =>
      ['critical_count','down_count','unreachable_count','error_count','error_failed_count','warning_count'].includes(k)
    ),
    used_nested_object: Object.keys(nested).length > 0
  },
  resolved_values: {
    totalLogLines,
    criticalCount,
    downCount,
    unreachableCount,
    errorCount,
    warningCount,
    criticalLogsFound: criticalLogs.length
  }
};

console.log('NAGIOS FIELD RESOLUTION DEBUG:', JSON.stringify(debugInfo, null, 2));


// ============================================================
// DETERMINE OVERALL STATUS
// ============================================================
//
// CRITICAL if ANY critical/down/unreachable/error exists
// WARNING  if no critical problems but warnings exist
// HEALTHY  only when everything is zero
//

let overallStatus = 'HEALTHY';

if (
  criticalCount > 0 ||
  downCount > 0 ||
  unreachableCount > 0 ||
  errorCount > 0
) {
  overallStatus = 'CRITICAL';
}
else if (warningCount > 0) {
  overallStatus = 'WARNING';
}


// ============================================================
// STATUS MESSAGE
// ============================================================

let statusMessage = '';

if (overallStatus === 'CRITICAL') {

  statusMessage =
    `Nagios detected ${criticalCount} CRITICAL, ` +
    `${downCount} DOWN, ` +
    `${unreachableCount} UNREACHABLE and ` +
    `${errorCount} ERROR/FAILED events. ` +
    `Immediate investigation is required.`;

}
else if (overallStatus === 'WARNING') {

  statusMessage =
    `Nagios detected ${warningCount} WARNING events. ` +
    `Please review the monitoring alerts.`;

}
else {

  statusMessage =
    'No CRITICAL, DOWN, UNREACHABLE, ERROR/FAILED or WARNING events detected.';

}


// ============================================================
// ESCAPE HTML
// ============================================================

function escapeHtml(value) {

  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

}


// ============================================================
// CREATE LOG TABLE
// ============================================================

function createRows(items, status) {

  if (!items || items.length === 0) {

    return `
      <tr>
        <td colspan="2"
            style="padding:10px;border:1px solid #ddd;">
          No ${status} events detected.
        </td>
      </tr>
    `;

  }

  return items.map((line, index) => {

    return `
      <tr>
        <td style="
          padding:8px;
          border:1px solid #ddd;
          width:50px;
          text-align:center;
        ">
          ${index + 1}
        </td>

        <td style="
          padding:8px;
          border:1px solid #ddd;
          font-family:monospace;
          font-size:12px;
        ">
          ${escapeHtml(line)}
        </td>
      </tr>
    `;

  }).join('');

}


// ============================================================
// REPORT DATE / TIME
// ============================================================

const reportDateTime = new Date().toLocaleString(
  'en-IN',
  {
    timeZone: 'Asia/Kolkata'
  }
);

const reportDate = new Date().toLocaleDateString(
  'en-IN',
  {
    timeZone: 'Asia/Kolkata'
  }
);


// ============================================================
// HTML STATUS COLORS
// ============================================================

let statusColor = '#16a34a';
let statusBackground = '#dcfce7';

if (overallStatus === 'CRITICAL') {

  statusColor = '#dc2626';
  statusBackground = '#fee2e2';

}
else if (overallStatus === 'WARNING') {

  statusColor = '#d97706';
  statusBackground = '#fef3c7';

}


